create table dj_a (id bigint generated by default as identity primary key, name varchar(50) not null, created timestamptz not null default now())
create table dj_b (id bigint generated by default as identity primary key, a_id bigint not null constraint dj_b_a_fk references dj_a(id) deferrable initially deferred, note text null)
alter table dj_b add constraint dj_b_a_fk2 foreign key (a_id) references dj_a(id) deferrable initially deferred
create index dj_a_name_like on dj_a (name varchar_pattern_ops)
create index dj_a_name_like2 on dj_a (name text_pattern_ops)
create index dj_a_name_idx on dj_a (name)
create unique index dj_a_uniq on dj_a (lower(name))
create index concurrently dj_a_created on dj_a (created desc)
set constraints all immediate
set constraints all deferred
set constraints dj_b_a_fk immediate
alter table dj_a add column c text not null default 'x'
alter table dj_a alter column c drop default
alter table dj_a alter column name type varchar(100)
alter table dj_a alter column name type varchar(120) using name::varchar(120)
alter table dj_a alter column name set not null
alter table dj_a alter column c drop not null
alter table dj_a rename column c to c2
alter table dj_a rename to dj_a2
alter table dj_a2 rename to dj_a
alter table dj_a drop column c2
alter table dj_a drop column if exists nope
alter table dj_b drop constraint dj_b_a_fk2
alter table dj_b alter constraint dj_b_a_fk deferrable initially immediate
alter table only dj_b add constraint dj_b_chk check (id > 0) not valid
alter table dj_b validate constraint dj_b_chk
select pg_get_serial_sequence('dj_a', 'id')
select setval(pg_get_serial_sequence('dj_a', 'id'), coalesce(max(id), 1), max(id) is not null) from dj_a
select pg_get_serial_sequence('"dj_a"', 'id') is not null
insert into dj_a (name) values ('one'), ('two') returning id
insert into dj_b (a_id, note) values (1, 'x')
begin
set constraints all deferred
insert into dj_b (a_id) values (999)
commit
select count(*) from dj_b
select c.relname, c.relkind from pg_catalog.pg_class c join pg_catalog.pg_namespace n on n.oid = c.relnamespace where n.nspname = 'public' and c.relname like 'dj_%' order by 1
select conname, contype, condeferrable, condeferred from pg_constraint where conrelid = 'dj_b'::regclass order by 1
select indexname from pg_indexes where tablename = 'dj_a' order by 1
select column_name, is_identity, identity_generation from information_schema.columns where table_name = 'dj_a' order by ordinal_position
select a.attname, a.attidentity from pg_attribute a where a.attrelid = 'dj_a'::regclass and a.attnum > 0 order by a.attnum
select tc.constraint_name, tc.is_deferrable, tc.initially_deferred from information_schema.table_constraints tc where tc.table_name = 'dj_b' order by 1
select typname from pg_type where typtype = 'e'
create type mood as enum ('sad', 'ok')
select e.enumlabel from pg_enum e join pg_type t on t.oid = e.enumtypid where t.typname = 'mood' order by e.enumsortorder
select t.typname, t.oid from pg_type t where t.typname in ('int4', 'text', 'bool', 'uuid', 'jsonb', 'varchar', 'timestamptz') order by 1
select oid::regtype from pg_type where typname = 'int4'
select 'int4'::regtype::oid
select 1::regtype
select atttypid::regtype from pg_attribute where attrelid = 'dj_a'::regclass and attname = 'id'
select format_type(atttypid, atttypmod) from pg_attribute where attrelid = 'dj_a'::regclass and attname = 'name'
select pg_get_indexdef(indexrelid) from pg_index where indrelid = 'dj_a'::regclass order by 1
select pg_get_constraintdef(oid) from pg_constraint where conrelid = 'dj_b'::regclass order by 1
select pg_catalog.pg_get_expr(adbin, adrelid) from pg_attrdef where adrelid = 'dj_a'::regclass
select relname, reltuples::bigint, relpages from pg_class where relname = 'dj_a'
select nspname from pg_namespace where nspname !~ '^pg_' and nspname <> 'information_schema' order by 1
select current_setting('server_version_num')::int >= 90600
select pg_catalog.set_config('search_path', '', false)
select set_config('search_path', 'public', false)
create table dj_c (id serial primary key, x integer not null check (x >= 0), y smallint, z real, w numeric(10, 2), u uuid, d date, ts timestamp)
create table dj_d (id uuid primary key default gen_random_uuid(), j jsonb not null default '{}', tags text[] not null default '{}', at timestamptz default now())
insert into dj_d default values
select id is not null, j, tags from dj_d
create table dj_e (a int, b int, primary key (a, b))
create table dj_f (like dj_e including all)
create table dj_g (id int primary key, parent int references dj_g(id) on delete cascade on update cascade)
create table dj_h (id int primary key, ref int unique)
create table dj_i (id int primary key, r int references dj_h(ref))
create sequence dj_seq start 10 increment 5 minvalue 1 maxvalue 1000 cache 1
select nextval('dj_seq'), nextval('dj_seq')
alter sequence dj_seq restart with 100
alter sequence dj_seq owned by dj_c.id
drop sequence dj_seq
create view dj_v as select id, name from dj_a
create or replace view dj_v as select id, name, created from dj_a
create materialized view dj_m as select id from dj_a
refresh materialized view dj_m
refresh materialized view concurrently dj_m
drop materialized view dj_m
drop view dj_v
alter table dj_a add column ts tsvector generated always as (to_tsvector('english', name)) stored
alter table dj_a add column len int generated always as (length(name)) stored
alter table dj_c add column full_name text generated always as (id::text || 'x') stored
alter table dj_a enable row level security
alter table dj_a owner to current_user
alter table dj_a set (fillfactor = 70)
alter table dj_a set schema public
alter table dj_a set tablespace pg_default
alter index dj_a_name_idx rename to dj_a_name_idx2
drop index concurrently if exists dj_a_name_idx2
drop index if exists nope_idx
drop table if exists dj_zzz cascade
truncate dj_b, dj_a restart identity cascade
select count(*) from dj_a
drop table dj_b, dj_a cascade
create schema if not exists dj_s authorization current_user
create table dj_s.t (id int)
drop schema dj_s cascade
create database dj_shadow
drop database if exists dj_shadow
